                cons[#cons + 1] = m:GetAttributeChangedSignal(attr):Connect(function() F.parryNow(attr) end)
            end
            S.watching[m] = cons
        end
    end
end
function F.unwatch()
    for _, cons in pairs(S.watching) do
        for _, c in ipairs(cons) do c:Disconnect() end
    end
    S.watching = {}
end
function F.swing(group)
    local r = M.root()
    if not r or not group[1] or not RUNNING or not M.ready() then return end
    while RUNNING and os.clock() < S.blockTill do task.wait(0.02) end
    r = M.root()
    if not r or not M.ready() then return end
    S.seq += 1
    local seq = S.seq
    local dir = group[1]:GetPivot().Position - r.Position
    if dir.Magnitude < 0.1 then dir = r.CFrame.LookVector end
    M.fire("SymbioteCombat", "atk", dir.Unit, seq)
    task.wait(0.16)
    if not RUNNING or not M.ready() then return end
    M.fire("SymbioteCombat", "hits", seq, group)
    task.wait(0.16)
end
function F.bestWeapon()
    if not on("f_weapon") or not D.Combat or not D.Combat.WeaponsFor then return end
    local c = lp.Character
    local kind = c and c:GetAttribute("SymbioteKind")
    if not kind then return end
    local ok, list = pcall(D.Combat.WeaponsFor, kind)
    if not ok or type(list) ~= "table" then return end
    local best, score
    for _, id in ipairs(list) do
        local w = D.Combat.Weapons and D.Combat.Weapons[id]
        if w and w.dmg and w.cd and w.cd > 0 then
            local sum = 0
            for _, d in ipairs(w.dmg) do sum += d end
            local s = sum / #w.dmg / w.cd
            if not score or s > score then best, score = id, s end
        end
    end
    if best and c:GetAttribute("Weapon") ~= best and M.cool("weapon", 3) then
        M.fire("SymbioteCombat", "weapon", best)
        LOG("weapon", best)
    end
end
function F.fightLoop(getList, maxSec, label, key)
    S.task = label
    F.bestWeapon()
    local t0, lastChg = os.clock(), os.clock()
    local lastHp, lastT, spot, spotAt, spotFor
    Q.liquid(false)
    S.stickY = nil
    do
        local list = { lp.Character }
        for _, n in ipairs({ "Civilians", "Enemies", "ActivityNPCs", "SummonedSymbiotes", "VFXRuntime", "CombatFX" }) do
            local x = Workspace:FindFirstChild(n)
            if x then list[#list + 1] = x end
        end
        local rp = RaycastParams.new()
        rp.FilterType = Enum.RaycastFilterType.Exclude
        rp.FilterDescendantsInstances = list
        rp.RespectCanCollide = true
        S.stickRp = rp
    end
    while RUNNING and M.ready() and M.bonded() and on("f_auto") and (not key or on(key)) and os.clock() - t0 < maxSec do
        local list = getList()
        if #list == 0 then S.fightTarget = nil return "clear" end
        if M.hp() < val("f_retreat", 30) then S.fightTarget = nil return "low" end
        local r = M.root()
        if not r then S.fightTarget = nil return "dead" end
        if lp.Character:GetAttribute("Liquid") then
            Q.liquid(false)
            task.wait(0.2)
        else
            local t = M.closest(list, r.Position)
            local p = t:GetPivot().Position
            S.fightTarget = t
            local fresh = false
            if t ~= spotFor or not spotAt or (not on("f_stick") and spot and (spot - F.back(t, p)).Magnitude > 5) then
                M.stream(p)
                p = t:GetPivot().Position
                spot = F.behind(t, p)
                spotAt, spotFor, fresh = p, t, true
            end
            if not spot then
                S.skip[t] = os.clock() + 15
                spotFor = nil
                task.wait(0.05)
            else
                if fresh or not on("f_stick") then F.pin(spot, p) end
                if on("f_ult") and M.cool("ult", (D.Combat and D.Combat.ULT_COOLDOWN or 4) + 0.15) then
                    M.fire("SymbioteCombat", "ult")
                    S.ults += 1
                end
                local group = {}
                for _, m in ipairs(list) do
                    if #group < 12 and (m:GetPivot().Position - p).Magnitude < 12 then group[#group + 1] = m end
                end
                F.watch(group)
                F.swing(group)
                local cur = hpOf(t)
                if t ~= lastT or cur ~= lastHp then
                    lastT, lastHp, lastChg = t, cur, os.clock()
                elseif os.clock() - lastChg > 8 then
                    S.skip[t] = os.clock() + 40
                    LOG("stuck", label, t.Name)
                    lastT = nil
                end
            end
        end
    end
    S.fightTarget = nil
    return "time"
end
function F.fight(...)
    local ok, r = pcall(F.fightLoop, ...)
    S.hold, S.fightTarget = nil, nil
    F.unwatch()
    if not ok then error(r) end
    return r
end
function F.eatOne(target)
    local r = M.root()
    if not r then return false end
    local m = target or M.closest(F.civs(), r.Position)
    if not m then task.wait(0.3) return false end
    M.stream(m:GetPivot().Position)
    if not m.Parent or not m.PrimaryPart then S.skip[m] = os.clock() + 10 task.wait(0.05) return false end
    local pos = m:GetPivot().Position
    local s = M.near(pos, { 3, 4, 5, 6, 8 }, 10)
    if not s then S.skip[m] = os.clock() + 20 task.wait(0.05) return false end
    if Q.liquidWanted() then Q.liquid(true) end
    if not RUNNING or not M.ready() then return false end
    M.go(s)
    task.wait(0.3)
    if not RUNNING or not M.ready() then return false end
    local stat = lp:FindFirstChild("leaderstats") and lp.leaderstats:FindFirstChild("Devoured")
    local before = stat and stat.Value or 0
    M.fire("SymbioteDevour", m)
    local t0 = os.clock()
    while RUNNING and os.clock() - t0 < 2.2 and stat and stat.Value == before do task.wait(0.03) end
    if stat and stat.Value > before then return true end
    S.skip[m] = os.clock() + 20
    return false
end
function F.heal(goal)
    S.task = __T["Healing"]
    local t0 = os.clock()
    local meals = 0
    while RUNNING and M.ready() and M.bonded() and on("f_auto") and M.hp() < goal and os.clock() - t0 < 20 do
        if F.eatOne() then meals += 1 else task.wait(0.2) end
    end
    if meals == 0 then S.healFail = os.clock() end
end
function F.canHeal() return os.clock() - (S.healFail or 0) > 15 end
function F.pick()
    if on("f_crime") and #F.crims() > 0 then return __T["Stopping crime"], F.crims, 30, "f_crime" end
    if on("f_brood") and #F.brood() > 0 then return __T["Clearing brood"], F.brood, 40, "f_brood" end
    if on("f_xeno") and #F.xenos() > 0 then return __T["Hunting Xenophage"], F.xenos, 40, "f_xeno" end
    if on("f_boss") and #F.bosses() > 0 then return __T["Fighting boss"], F.bosses, 90, "f_boss" end
end
function F.tick()
    if not Q.liquidWanted() then pcall(Q.liquid, false) end
    if not on("f_auto") or not M.ready() then
        S.task = on("f_pause") and __T["Paused"] or __T["Idle"]
        task.wait(0.4)
        return
    end
    if not M.bonded() then
        S.task = __T["Waiting for suit"]
        task.wait(0.4)
        return
    end
    if Q.need("eatCriminal") and on("q_eatcrim") then
        local m = M.closest(F.crims(), M.root().Position)
        if m and M.cool("eatcrim", 25) then
            S.task = __T["Eating criminal"]
            local ok = F.eatOne(m)
            LOG("eat criminal", ok)
            S.skip[m] = nil
            return
        end
    end
    if on("q_suit") and Q.need("suit") and M.cool("suitq", 8) then
        S.task = __T["Suit quest"]
        Q.liquid(false)
        M.fire("SymbioteToggle")
        task.wait(2.6)
        M.fire("SymbioteToggle")
        task.wait(2.4)
        return
    end
    if on("q_possess") and Q.need("possess") and M.cool("possess", 4) then
        Q.possess()
        return
    end
    local label, fn, max, key = F.pick()
    if fn then
        if M.hp() < val("f_heal", 70) and F.canHeal() then F.heal(95) return end
        if M.hp() < val("f_retreat", 30) then
            S.task = __T["Recovering"]
            task.wait(1)
            return
        end
        local r = F.fight(fn, max, label, key)
        if r == "low" and F.canHeal() then F.heal(90) end
        return
    end
    if on("f_devour") then
        S.task = __T["Devouring"]
        if not F.eatOne() then task.wait(0.3) end
        return
    end
    S.task = __T["Waiting for targets"]
    task.wait(0.5)
end
task.spawn(function()
    while RUNNING do
        local ok, e = pcall(F.tick)
        if not ok then LOG("farm err", tostring(e)) task.wait(1) end
        task.wait()
    end
end)
