function Q.wall()
    if S.wallAt and os.clock() - S.wallAt < 8 then return S.wallP, S.wallN end
    local r = M.root()
    if not r then return end
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { lp.Character, Workspace:FindFirstChild("Civilians") }
    for i = 0, 23 do
        local a = i / 24 * math.pi * 2
        local h = Workspace:Raycast(r.Position + Vector3.new(0, 3, 0), Vector3.new(math.cos(a) * 150, 20, math.sin(a) * 150), rp)
        if h and math.abs(h.Normal.Y) < 0.2 then
            S.wallP, S.wallN, S.wallAt = h.Position, h.Normal, os.clock()
            return h.Position, h.Normal
        end
    end
end
