function Q.mutate()
    if on("f_pause") or not on("u_auto") or not D.Prog or not D.Prog.MutationById or not M.cool("mut", 2) then return end
    local maxLv = D.Prog.MUT_MAX or 3
    local order = { "gland", "ties", "reach", "stride", "tether", "gut", "metab", "spring", "grip" }
    local keep = tonumber(val("u_keep", "0")) or 0
    local function buy(m, lv)
        local ok, why = M.prog("buyMutation", m.id)
        task.wait(0.4)
        if M.num("Mut_" .. m.id) > lv then
            S.muts += 1
            LOG("mutation", m.id, lv + 1)
            S.cool["mut"] = os.clock() + 15
            return true
        end
        LOG("mutation fail", m.id, ok, why)
        S.cool["mut"] = os.clock() + 12
        return false
    end
    for _, m in ipairs(D.Prog.Mutations or {}) do
        if m.currency == "genome" then
            local lv = M.num("Mut_" .. m.id)
            local cost = m.costs[lv + 1]
            if lv < maxLv and cost and M.num("Genomes") >= cost then buy(m, lv) return end
        end
    end
    for _, id in ipairs(order) do
        local m = D.Prog.MutationById[id]
        if m then
            local lv = M.num("Mut_" .. id)
            local cost = m.costs[lv + 1]
            if lv < maxLv and cost then
                if M.num("Shards") - cost >= keep then buy(m, lv) end
                return
            end
        end
    end
end
