function P.tp(name)
    local r = M.root()
    if not r then return end
    local at
    if name == "Nearest Xenophage" then
        local m = M.closest(F.xenos(), r.Position)
        at = m and m:GetPivot().Position
    elseif name == "City Boss" then
        local m = F.bosses()[1]
        at = m and m:GetPivot().Position
    elseif name == "Nearest Crime" then
        local m = M.closest(F.crims(), r.Position)
        at = m and m:GetPivot().Position or (S.alert and os.clock() - S.alert.at < 60 and S.alert.pos) or nil
    elseif name == "Meteor Site" then
        local m = M.closest(F.brood(), r.Position)
        at = m and m:GetPivot().Position
    elseif name == "Food Cart" then
        local f = Workspace:FindFirstChild("FoodCarts")
        local m = f and M.closest(f:GetChildren(), r.Position)
        at = m and m:GetPivot().Position
    elseif name == "Shop Board" then
        local f = Workspace:FindFirstChild("ShopBoard")
        local m = f and f:GetChildren()[1]
        at = m and m:GetPivot().Position
    end
    if at then M.stream(at) end
    local s = at and M.near(at, { 6, 8, 10, 14, 18, 24 })
    if s then M.go(s) else notify(__T["Not available right now"]) end
end
function P.hop()
    task.spawn(function()
        local ok, data = pcall(function()
            return HttpService:JSONDecode(game:HttpGet("https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&excludeFullGames=true&limit=100"))
        end)
        if ok and type(data) == "table" and data.data then
            local pool = {}
            for _, s in ipairs(data.data) do if s.id ~= game.JobId and s.playing and s.playing < s.maxPlayers then pool[#pool + 1] = s.id end end
            if #pool > 0 then
                TeleportService:TeleportToPlaceInstance(game.PlaceId, pool[math.random(1, #pool)], lp)
                return
            end
        end
        notify(__T["No other server found"])
    end)
end
