function ESP.draw()
    if os.clock() - ESP.at < 0.1 then return end
    ESP.at = os.clock()
    local items = {}
    local function add(list, name, c)
        for _, m in ipairs(list) do if #items < 40 then items[#items + 1] = { m, name, c } end end
    end
    if on("e_xeno") then add(F.xenos(), "Xenophage", Color3.fromRGB(255, 90, 90)) end
    if on("e_boss") then add(F.bosses(), "BOSS", Color3.fromRGB(255, 200, 60)) end
    if on("e_crime") then add(F.crims(), "Criminal", Color3.fromRGB(110, 190, 255)) end
    local cam, r = Workspace.CurrentCamera, M.root()
    local n = 0
    if cam and r then
        for _, it in ipairs(items) do
            local p = it[1]:GetPivot().Position
            local v, vis = cam:WorldToViewportPoint(p)
            if vis then
                n += 1
                local d = ESP.pool[n]
                if not d then
                    d = Drawing.new("Text")
                    d.Center, d.Outline, d.Size = true, true, 14
                    ESP.pool[n] = d
                end
                d.Text = string.format("%s  %d", it[2], (p - r.Position).Magnitude)
                d.Color = it[3]
                d.Position = Vector2.new(v.X, v.Y)
                d.Visible = true
            end
        end
    end
    ESP.clear(n + 1)
end
